// Sponsor and alumni logos: white silhouettes generated by `npm run images` from
// assets-src/logos/. `w`/`h` are the generated image's pixel size; `scale` nudges
// logos whose thin strokes read small at the shared size. Sponsors can also have
// `url` (their logo links there) and `tier` (see SPONSOR_TIERS).
const files = import.meta.glob('./assets/logos/*.webp', { eager: true, import: 'default' });
const src = (name) => files[`./assets/logos/${name}.webp`];

const logo = (file, name, w, h, scale = 1) => ({ name, src: src(file), w, h, scale });

// Display height for a logo so wide wordmarks and square marks look equally weighted:
// every logo gets the same visual `area` (px²), capped at `maxH`, then its own `scale`.
export const logoHeight = ({ w, h, scale = 1 }, area, maxH) => Math.round(Math.min(maxH, Math.sqrt(area / (w / h)) * scale));

// Sponsorship levels from the packet, highest first. Sponsors without a `tier`
// are listed together under "Sponsors and partners".
export const SPONSOR_TIERS = ['Scarlet Knight', 'Knight', 'Squire'];

// Set `tier` to one of SPONSOR_TIERS to group a sponsor under that level.
